         {
-            if (smpp_mktime(strval, &tmptime.secs, &tmptime.nsecs))
+            if (relative) {
                 proto_tree_add_time(tree, field_R, tvb, *offset, len, &tmptime);
-            else
+            } else {
                 proto_tree_add_time(tree, field, tvb, *offset, len, &tmptime);
+            }
         }
         else
         {
-            tmptime.secs = 0;
-            tmptime.nsecs = 0;
